# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İBADETLERİN BİREYSEL FAYDALARI: HUZUR, AHLAK VE ÖZ DİSİPLİN (2.1.3)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. İmanı Koruma ve Huzur</text>\n  <text x="30" y="92" font-size="10" fill="#1e3a8a">• İbadet, kalpteki soyut imanı</text>\n  <text x="38" y="107" font-size="10" fill="#1e3a8a">somut davranışa dönüştürerek</text>\n  <text x="38" y="122" font-size="10" font-weight="bold" fill="#1d4ed8">inancı canlı tutar.</text>\n  <text x="30" y="143" font-size="10" fill="#1e3a8a">• Kul ile Rabbi arasındaki bağı</text>\n  <text x="38" y="158" font-size="10" fill="#1e3a8a">güçlendirir; yalnızlık, kaygı ve</text>\n  <text x="38" y="173" font-size="10" fill="#1e3a8a">ümitsizliği giderir (<tspan font-weight="bold">sekînet</tspan>).</text>\n  <rect x="30" y="186" width="190" height="42" rx="5" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="203" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e40af">"Kalpler ancak Allah\'ı anmakla</text>\n  <text x="125" y="218" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e40af">huzur bulur." (Ra\'d, 13/28)</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. Ahlaki Arınma ve Kalkan</text>\n  <text x="255" y="92" font-size="10" fill="#14532d">• <tspan font-weight="bold">Namaz:</tspan> İnsanı hayasızlıktan</text>\n  <text x="263" y="107" font-size="10" fill="#14532d">(<tspan font-weight="bold">fahşâ</tspan>) ve kötülükten (<tspan font-weight="bold">münker</tspan>)</text>\n  <text x="263" y="122" font-size="10" font-weight="bold" fill="#15803d">alıkoyar (Ankebût, 29/45).</text>\n  <text x="255" y="143" font-size="10" fill="#14532d">• <tspan font-weight="bold">Oruç:</tspan> İradeyi terbiye eder, sabır</text>\n  <text x="263" y="158" font-size="10" fill="#14532d">ve takva kazandırır (<tspan font-weight="bold">"Oruç kalkandır"</tspan>).</text>\n  <text x="255" y="179" font-size="10" fill="#14532d">• <tspan font-weight="bold">Zekât:</tspan> Bireyi cimrilik, bencillik</text>\n  <text x="263" y="194" font-size="10" fill="#14532d">ve mal hırsından temizler</text>\n  <text x="263" y="209" font-size="10" font-weight="bold" fill="#166534">(Tevbe, 9/103).</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">3. Öz Disiplin ve Temizlik</text>\n  <text x="480" y="92" font-size="10" fill="#78350f">• <tspan font-weight="bold">Zaman Bilinci:</tspan> Günde 5 vakit</text>\n  <text x="488" y="107" font-size="10" fill="#78350f">namaz, yılda 1 ay oruç insanın</text>\n  <text x="488" y="122" y2="122" font-size="10" font-weight="bold" fill="#b45309">hayatını planlı ve düzenli kılar.</text>\n  <text x="480" y="143" font-size="10" fill="#78350f">• <tspan font-weight="bold">Maddi-Manevi Temizlik:</tspan></text>\n  <text x="488" y="158" font-size="10" fill="#78350f">Abdest, gusül ve beden-elbise</text>\n  <text x="488" y="173" font-size="10" fill="#78350f">temizliği (<tspan font-weight="bold">taharet</tspan>) hijyen sağlar.</text>\n  <text x="480" y="194" font-size="10" fill="#78350f">• <tspan font-weight="bold">Sorumluluk Bilinci:</tspan> Allah\'ın</text>\n  <text x="488" y="209" font-size="10" fill="#78350f">huzurunda hesap verme şuuru</text>\n  <text x="488" y="224" font-size="10" font-weight="bold" fill="#92400e">bireye öz denetim kazandırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İBADETLERİN TOPLUMSAL YÖNÜ: KARDEŞLİK, EŞİTLİK VE SOSYAL ADALET (2.1.3)</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Birlik, Beraberlik ve Eşitlik Bilinci</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Cemaatle Namaz, Cuma ve Bayram:</tspan></text>\n  <text x="40" y="107" font-size="10" fill="#1e3a8a">Aynı mahalle ve şehir insanlarını günde 5 kez ve</text>\n  <text x="40" y="122" font-size="10" fill="#1e3a8a">haftada 1 kez omuz omuza aynı safta buluşturur;</text>\n  <text x="40" y="137" font-size="10" font-weight="bold" fill="#1d4ed8">küskünlükleri ve statü farklarını ortadan kaldırır.</text>\n  <text x="32" y="160" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Hac İbadeti (Evrensel Kongre):</tspan></text>\n  <text x="40" y="175" font-size="10" fill="#1e3a8a">Farklı ırk, dil ve ülkelerden milyonlarca Müslüman</text>\n  <text x="40" y="190" font-size="10" fill="#1e3a8a">bembeyaz <tspan font-weight="bold">ihram</tspan> içinde Kâbe ve Arafat\'ta</text>\n  <text x="40" y="205" font-size="10" font-weight="bold" fill="#1e40af">tüm insanların Allah katında eşitliğini yaşar.</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">2. Sosyal Adalet, Empati ve Yardımlaşma</text>\n  <text x="372" y="92" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Zekât, Sadaka, Fitre ve Kurban:</tspan></text>\n  <text x="380" y="107" font-size="10" fill="#581c87">Servetin yalnız zenginler arasında dolaşan bir güç</text>\n  <text x="380" y="122" font-size="10" fill="#581c87">olmasını önler (Haşr, 59/7); zengin ile yoksul</text>\n  <text x="380" y="137" font-size="10" font-weight="bold" fill="#7e22ce">arasındaki sevgi ve güven köprüsünü kurar.</text>\n  <text x="372" y="160" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Oruç ve İftar Sofraları:</tspan></text>\n  <text x="380" y="175" font-size="10" fill="#581c87">Varlıklı insanların açların ve yoksulların halini</text>\n  <text x="380" y="190" font-size="10" fill="#581c87">bizzat yaşayarak anlamasını (<tspan font-weight="bold">empati / diğerkâmlık</tspan>)</text>\n  <text x="380" y="205" font-size="10" font-weight="bold" fill="#6b21a8">ve nimetleri paylaşmasını sağlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. PEYGAMBER\'İN İBADET HAYATINDAKİ İTİDAL (DENGE VE ÖLÇÜLÜLÜK) İLKESİ (2.1.4)</text>\n  <rect x="20" y="45" width="200" height="140" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="120" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">TEFRİT (İhmal / Gevşeklik)</text>\n  <text x="32" y="92" font-size="10" fill="#7f1d1d">• Yalnız dünyaya dalıp</text>\n  <text x="40" y="107" font-size="10" fill="#7f1d1d">ahireti ve kulluk görevlerini</text>\n  <text x="40" y="122" font-size="10" fill="#7f1d1d">tamamen terk etmek.</text>\n  <text x="120" y="165" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">✖ İslam Reddeder</text>\n  <rect x="235" y="45" width="230" height="140" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İTİDAL (Orta Yol / Denge)</text>\n  <text x="247" y="92" font-size="10" fill="#14532d">• <tspan font-weight="bold">Dünya ve Ahiret Dengesi</tspan> (Kasas, 77)</text>\n  <text x="247" y="109" font-size="10" fill="#14532d">• <tspan font-weight="bold">Sünnet Ölçüsü:</tspan> "Hem namaz kılarım</text>\n  <text x="255" y="124" font-size="10" fill="#14532d">hem uyurum; hem oruç tutarım hem</text>\n  <text x="255" y="139" font-size="10" fill="#14532d">yerim; evlenirim..." (Buhârî)</text>\n  <text x="350" y="165" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">✔ "Az da olsa devamlı olan amel!"</text>\n  <rect x="480" y="45" width="200" height="140" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="580" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">İFRAT (Aşırılık / Ruhbanlık)</text>\n  <text x="492" y="92" font-size="10" fill="#7f1d1d">• Dünyadan el etek çekmek,</text>\n  <text x="500" y="107" font-size="10" fill="#7f1d1d">uykusuz/evlenmeden yaşamak,</text>\n  <text x="500" y="122" font-size="10" fill="#7f1d1d">bedene ve aileye eziyet etmek.</text>\n  <text x="580" y="165" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">✖ İslam Reddeder</text>\n  <rect x="20" y="195" width="660" height="48" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="214" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Hz. Peygamber\'in Abdullah bin Amr\'a Uyarısı: "Şüphesiz Rabb\'inin senin üzerinde hakkı vardır;</text>\n  <text x="350" y="231" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">nefsinin (bedeninin), ailenin ve misafirinin senin üzerinde hakkı vardır. Her hak sahibine hakkını ver!"</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
